pub fn servStar(gpaz: std.mem.Allocator, iozz: std.Io, port: u16, uizz_root: []const u8, sche: *tick.Sche) !void { var addr = try std.Io.net.IpAddress.parseIp4("127.0.0.1", port); var list = try addr.listen(iozz, .{ .mode = .stream, .reuse_address = true }); defer list.deinit(iozz); var ctxz = Ctxz{ .gpaz = gpaz, .iozz = iozz, .uizz_root = uizz_root, .sche = sche, .cach = .{ .gpaz = gpaz, .root = uizz_root } }; ctxz.regz.gpaz = gpaz; defer ctxz.regz.dein(gpaz); defer ctxz.sess.dein(gpaz); defer ctxz.watc.dein(gpaz, iozz); ctxz.shel_json = shelJson(gpaz, iozz); if (std.Thread.spawn(.{ .stack_size = CF.reap_stak }, reapMain, .{&ctxz})) |thrd| thrd.detach() else |_| {} bannPrin(port, uizz_root); while (true) { const strm = list.accept(iozz) catch { std.Io.sleep(iozz, .fromMilliseconds(CF.back_msec), .awake) catch {}; continue; }; const slot_inde = slotAcqu(&ctxz, iozz) orelse { busyRepl(iozz, strm); continue; }; const boxz = gpaz.create(std.Io.net.Stream) catch { slotRele(&ctxz, iozz, slot_inde); strm.close(iozz); continue; }; boxz.* = strm; slotStrmSetz(&ctxz, iozz, slot_inde, boxz); const thrd = std.Thread.spawn(.{ .stack_size = CF.conn_stak }, taskHand, .{ &ctxz, boxz, slot_inde }) catch { slotRele(&ctxz, iozz, slot_inde); boxz.close(iozz); gpaz.destroy(boxz); continue; }; thrd.detach(); } }
fn busyRepl(iozz: std.Io, strm: std.Io.net.Stream) void { var writ_buff: [256]u8 = undefined; var strm_writ = strm.writer(iozz, &writ_buff); http.respSend(&strm_writ, 503, "Service Unavailable", "{\"error\":\"busy\"}") catch {}; strm.close(iozz); }
fn slotAcqu(ctxz: *Ctxz, iozz: std.Io) ?usize { ctxz.slot_mute.lock(iozz) catch return null; defer ctxz.slot_mute.unlock(iozz); for (&ctxz.slot, 0..) |*slot, inde| { if (slot.sinc != 0) continue; slot.* = .{ .sinc = spaw.nowzMsec(iozz), .arme = true }; return inde; } return null; }
fn slotStrmSetz(ctxz: *Ctxz, iozz: std.Io, inde: usize, strm: *std.Io.net.Stream) void { ctxz.slot_mute.lock(iozz) catch return; defer ctxz.slot_mute.unlock(iozz); ctxz.slot[inde].strm = strm; }
fn slotDisa(ctxz: *Ctxz, iozz: std.Io, inde: usize) void { ctxz.slot_mute.lock(iozz) catch return; defer ctxz.slot_mute.unlock(iozz); ctxz.slot[inde].arme = false; }
fn slotRele(ctxz: *Ctxz, iozz: std.Io, inde: usize) void { ctxz.slot_mute.lock(iozz) catch return; defer ctxz.slot_mute.unlock(iozz); ctxz.slot[inde] = .{}; }
fn reapMain(ctxz: *Ctxz) void { const iozz = ctxz.iozz; while (true) { std.Io.sleep(iozz, .fromMilliseconds(CF.reap_msec), .awake) catch return; const nowz = spaw.nowzMsec(iozz); ctxz.slot_mute.lock(iozz) catch continue; for (&ctxz.slot) |*slot| { if (!slot.arme or slot.sinc == 0) continue; if (nowz - slot.sinc < CF.head_dead_msec) continue; if (slot.strm) |strm| strm.shutdown(iozz, .both) catch {}; slot.arme = false; } ctxz.slot_mute.unlock(iozz); } }
fn taskHand(ctxz: *Ctxz, conn: *std.Io.net.Stream, slot_inde: usize) void { const iozz = ctxz.iozz; defer ctxz.gpaz.destroy(conn); defer conn.close(iozz); defer slotRele(ctxz, iozz, slot_inde); var aren = std.heap.ArenaAllocator.init(ctxz.gpaz); defer aren.deinit(); connHand(ctxz, aren.allocator(), iozz, conn, slot_inde) catch {}; }
fn connHand(ctxz: *Ctxz, allo: std.mem.Allocator, iozz: std.Io, conn: *std.Io.net.Stream, slot_inde: usize) !void { var read_buff: [CF.requ_buff]u8 = undefined; var strm_read = conn.reader(iozz, &read_buff); var writ_buff: [CF.writ_buff]u8 = undefined; var strm_writ = conn.writer(iozz, &writ_buff); var line_buff: [CF.line_buff]u8 = undefined; const requ = http.requRead(&strm_read, &line_buff) catch |erro| { if (http.statErro(erro)) |info| http.respSend(&strm_writ, info.code, info.text, "{\"error\":\"bad_request\"}") catch {}; return; }; const path = http.pathOnly(requ.path); const quer = http.pathQuer(requ.path); const meth_getz = std.mem.eql(u8, requ.meth, "GET"); const meth_post = std.mem.eql(u8, requ.meth, "POST"); const page_getz = meth_getz and (std.mem.eql(u8, path, "/") or std.mem.endsWith(u8, path, ".html")); switch (http.gate(requ, page_getz)) { .okay => {}, .host => return http.respSend(&strm_writ, 403, "Forbidden", "{\"error\":\"host_not_allowed\"}"), .orig => return http.respSend(&strm_writ, 403, "Forbidden", "{\"error\":\"origin_not_allowed\"}"), .fetc_site => return http.respSend(&strm_writ, 403, "Forbidden", "{\"error\":\"cross_site\"}") } if (std.mem.eql(u8, requ.meth, "OPTIONS")) { try strm_writ.interface.writeAll("HTTP/1.1 204 No Content\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"); try strm_writ.interface.flush(); return; } if (requ.chun) return http.respSend(&strm_writ, 411, "Length Required", "{\"error\":\"chunked_unsupported\"}"); if (requ.cont_leng > CF.body_maxz) return http.respSend(&strm_writ, 413, "Payload Too Large", "{\"error\":\"too_large\"}"); const body: ?[]u8 = if (requ.cont_leng > 0) http.bodyRead(allo, &strm_read, requ.cont_leng, CF.body_maxz) else null; if (requ.cont_leng > 0 and body == null) return; slotDisa(ctxz, iozz, slot_inde); const rout = Rout{ .ctxz = ctxz, .allo = allo, .iozz = iozz, .strm = &strm_writ, .requ = requ, .quer = quer, .body = body }; if (meth_getz) { if (std.mem.eql(u8, path, "/ping")) return rout.pin